package cn.cccs7.cynexus.market.infra.portfolio;
import cn.cccs7.cynexus.market.domain.portfolio.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class PortfolioAccountSnapshotRepositoryAdapter implements PortfolioAccountSnapshotRepository {
 private final JdbcTemplate jdbc; private final PortfolioIdGenerator ids; public PortfolioAccountSnapshotRepositoryAdapter(JdbcTemplate jdbc,PortfolioIdGenerator ids){this.jdbc=jdbc;this.ids=ids;}
 public List<PortfolioAccountSnapshotBO> list(String p,String t){return jdbc.query("select id,snapshot_date,total_assets,available_cash,market_value,net_deposit,net_withdrawal,daily_pnl,daily_return from cynexus_appl_market.portfolio_account_snapshot where principal_key=? and tenant_key=? order by snapshot_date",(r,n)->new PortfolioAccountSnapshotBO(r.getLong(1),r.getDate(2).toLocalDate(),r.getBigDecimal(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9)),p,t);}
 public PortfolioAccountSnapshotBO upsert(String p,String t,PortfolioAccountSnapshotBO s){long id=s.id()==null?ids.nextId():s.id();jdbc.update("insert into cynexus_appl_market.portfolio_account_snapshot(id,principal_key,tenant_key,snapshot_date,total_assets,available_cash,market_value,net_deposit,net_withdrawal,daily_pnl,daily_return) values(?,?,?,?,?,?,?,?,?,?,?) on conflict(tenant_key,principal_key,snapshot_date) do update set total_assets=excluded.total_assets,available_cash=excluded.available_cash,market_value=excluded.market_value,net_deposit=excluded.net_deposit,net_withdrawal=excluded.net_withdrawal,daily_pnl=excluded.daily_pnl,daily_return=excluded.daily_return",id,p,t,s.snapshotDate(),s.totalAssets(),s.availableCash(),s.marketValue(),s.netDeposit(),s.netWithdrawal(),s.dailyPnl(),s.dailyReturn());return new PortfolioAccountSnapshotBO(id,s.snapshotDate(),s.totalAssets(),s.availableCash(),s.marketValue(),s.netDeposit(),s.netWithdrawal(),s.dailyPnl(),s.dailyReturn());}
}
